tests:
test({ sr: 'zadržava reči sa bar min slova', en: 'keeps words with at least min letters' }, () => {
  expect(longWords(['a', 'bb', 'ccc', 'dd'], 2)).toEqual(['bb', 'ccc', 'dd']);
});
test({ sr: 'reč sa tačno min slova ulazi', en: 'a word with exactly min letters goes in' }, () => {
  expect(longWords(['cat', 'dog'], 3)).toEqual(['cat', 'dog']);
});
test({ sr: 'nijedna reč ne ulazi', en: 'no word goes in' }, () => {
  expect(longWords(['a', 'b'], 5)).toEqual([]);
});

hiddenTests:
test('only the longer word stays', () => {
  expect(longWords(['cat', 'house'], 4)).toEqual(['house']);
});
test('min 0 keeps everything, even the empty text', () => {
  expect(longWords(['', 'a'], 0)).toEqual(['', 'a']);
});
test('keeps the original order', () => {
  expect(longWords(['dddd', 'a', 'bbb', 'cc'], 2)).toEqual(['dddd', 'bbb', 'cc']);
});
test('an empty array gives an empty array', () => {
  expect(longWords([], 3)).toEqual([]);
});
test('does not change the input and returns a new array', () => {
  const input = ['cat', 'dog'];
  const result = longWords(input, 3);
  expect(input).toEqual(['cat', 'dog']);
  expect(result).not.toBe(input);
});

